def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """A power-law model for log10(|ID|/A)."""
    a, b, c, d = parameters
    return np.log10(np.abs(a * (gate_voltage_abs**b) * (drain_voltage_abs**c) * np.exp(-d * (gate_voltage_abs**2) * (drain_voltage_abs**2))))
